INSERT INTO `wp_addonlibrary_addons` VALUES (1,'Pricing Table Flip Box','pricing_flip_box_elementor','pricing_flip_box','elementor','The Pricing Table Flip Box enables you to elegantly display the prices of your products, services, or packages in a captivating flip box pricing table design.',1,'{\"html\":\"<div class=\\\"card {{show_hovered}}\\\" id=\\\"{{uc_id}}\\\">\\n  <div class=\\\"card__side card__side--front-1\\\">\\n    {% if show_graphic_element  == \\\"true\\\" %}\\n      <div class=\\\"ueGraphicEl\\\">\\n        {% if graphic_element_source == \\\"icon\\\" %}{{icon_html|raw}}{% endif %}\\n        {% if graphic_element_source == \\\"image\\\" %} <img src=\\\"{{graphic_image}}\\\" {{graphic_image_attributes|raw}}> {% endif %}\\n        {% if graphic_element_source == \\\"text\\\" %} <span>{{graphic_el_text|raw}}<\\/span> {% endif %}\\n      <\\/div>\\n    {% endif %}\\n    {% if show_title  == \\\"true\\\" %}<div class=\\\"card__heading\\\">{{title|raw}}<\\/div>{% endif %}\\n    {% if show_list  == \\\"true\\\" %}\\n      <div class=\\\"card__details\\\">\\n        <ul class=\\\"uc-items-wrapper {{uc_filtering_addclass}}\\\" {{uc_filtering_attributes|raw}}>\\n          {{put_items()}}\\n        <\\/ul>\\n      <\\/div>\\n    {% endif %}\\n  <\\/div>\\n  <div class=\\\"card__side card__side--back card__side--back-1\\\">\\n    <div class=\\\"card__cta\\\">\\n      <div class=\\\"card__price-box\\\">\\n        {% if show_description  == \\\"true\\\" %}<div class=\\\"ue_card_desc\\\">{{description|raw}}<\\/div>{% endif %}\\n        {% if show_subtitle   == \\\"true\\\" %}<div class=\\\"ue_card_subtitle\\\">{{subtitle|raw}}<\\/div>{% endif %}\\n        {% if show_price  == \\\"true\\\" %}<div class=\\\"card__price-value\\\">{{price|raw}}<\\/div>{% endif %}\\n      <\\/div>\\n      {% if show_btn  == \\\"true\\\" %}\\n        <div class=\\\"ue_flip_btn_wrapper\\\">\\n          <a href=\\\"{{button_link}}\\\" {{button_link_html_attributes|raw}} class=\\\"ue_flip_pricing_table_btn\\\">{{button_text|raw}}<\\/a>\\n        <\\/div>\\n      {% endif %}\\n    <\\/div>\\n  <\\/div>\\n<\\/div>\",\"html_item\":\"<li class=\\\"ue-list-item {{item.item_repeater_class}}\\\">{{item.title|raw}}<\\/li>\",\"css\":\"#{{uc_id}} * {\\n    box-sizing: border-box;\\n}\\n#{{uc_id}} {\\n    perspective: 150rem;\\n    position: relative;\\n    color: white;\\n    font-size: 16px;\\n    display: grid;\\n}\\n\\n#{{uc_id}} .ue_card_desc{\\n  width:100%;\\n}\\n\\n{% if show_btn  == \\\"true\\\" %}\\n#{{uc_id}} .ue_flip_btn_wrapper{\\n  display:flex;\\n}\\n#{{uc_id}} .ue_flip_pricing_table_btn {\\n    text-decoration: none;\\n    display: inline-block;\\n    transition: all 0.2s;\\n    position: relative;\\n    cursor: pointer;\\n}\\n\\n{% endif %}\\n#{{uc_id}} .card__side {\\n    grid-area: 1 \\/ 1 \\/ 1 \\/ 1;\\n    top: 0;\\n    left: 0;\\n    width: 100%;\\n    backface-visibility: hidden;\\n    overflow: hidden;\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    align-items: center;\\n  -webkit-backface-visibility:hidden;\\n    backface-visibility:hidden;\\n}\\n#{{uc_id}} .card__side--back {\\n    -webkit-transform: rotateY(180deg);\\n    transform: rotateY(180deg);\\n}\\n#{{uc_id}}:hover .card__side--back {\\n    -webkit-transform: rotateY(0);\\n    transform: rotateY(0);\\n}\\n#{{uc_id}}.ueHoverState .card__side--back{\\n    -webkit-transform: rotateY(0);\\n    transform: rotateY(0);\\n}\\n{% if show_list  == \\\"true\\\" %}\\n#{{uc_id}} .card__details ul {\\n  list-style: none;\\n  margin: 0 auto;\\n  padding: 0;\\n  width:100%;\\n}\\n#{{uc_id}} .card__details ul li:last-child {\\n    border-bottom: none;\\n}\\n{% endif %}\\n#{{uc_id}} .card__cta {\\n    text-align: center;\\n}\\n#{{uc_id}} .card__price-box {\\n    text-align: center;\\n}\\n#{{uc_id}}:hover .card__side--front-1 {\\n    -webkit-transform: rotateY(-180deg);\\n    transform: rotateY(-180deg);\\n    z-index: 2;\\n}\\n\\/* front side*\\/\\n{% if show_graphic_element  == \\\"true\\\" %}\\n#{{uc_id}} .ueGraphicEl {\\n  display:flex;\\n  align-items: center;\\n  justify-content: center;\\n  overflow:hidden;\\n}\\n#{{uc_id}} .ueGraphicEl svg{\\n  width:1em;\\n  height:1em;\\n}\\n{% endif %}\\n\\/*soft defaults*\\/\\n{% if show_title  == \\\"true\\\" %}\\n.card__heading {\\n  font-size: 42px;\\n  width:100%;\\n}\\n{% endif %}\\n{% if show_price  == \\\"true\\\" %}\\n.card__price-value {\\n  font-size: 35px;\\n  font-weight: 100;\\n  width:100%;\\n}\\n{% endif %}\\n{% if show_subtitle  == \\\"true\\\" %}\\n.ue_card_subtitle{\\n  font-size: 25px;\\n  width:100%;\\n}\\n{% endif %}\\n.ue_flip_pricing_table_btn{\\n  font-size: 18px;\\n}\"}','{\"options\":{\"enable_items\":1,\"items_section_title\":\"\",\"items_section_heading\":\"\",\"items_title_field\":\"\",\"path_assets\":\"pricing_table_flip_box\",\"js_as_module\":false,\"addon_icon\":\"fas fa-tag\",\"dynamic_addon\":\"false\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"The Pricing Table Flip Box enables you to elegantly display the prices of your products, services, or packages in a captivating flip box pricing table design.\",\"link_resource\":\"\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/pricing-table-flip-box-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size\":\"column\",\"preview_custom_width\":\"\",\"preview_bgcol\":\"#ffffff\",\"special\":\"\",\"special_data\":\"\",\"is_free_addon\":false,\"is_new_addon\":false,\"is_trending\":false},\"params\":[{\"type\":\"uc_radioboolean\",\"title\":\"Show Graphic Element\",\"name\":\"show_graphic_element\",\"description\":\"\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":[],\"condition_attribute2\":\"\",\"condition_operator2\":\"equal\",\"condition_value2\":null,\"label_block\":false,\"tabname\":\"\",\"default_value\":\"true\",\"true_name\":\"Yes\",\"true_value