\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"18\",\"right\":\"24\",\"bottom\":\"18\",\"left\":\"24\",\"isLinked\":false},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"25\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"d24e7f78\",\"elType\":\"widget\",\"settings\":{\"title\":\"\\u201cThis is what purity tastes like. This feels like home.\\u201d\",\"header_size\":\"h4\",\"title_color\":\"#ffd700\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Outfit\",\"typography_font_size\":{\"unit\":\"px\",\"size\":20},\"typography_font_style\":\"italic\",\"typography_font_weight\":\"600\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true},{\"id\":\"7d90ba44\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>That experience inspired a dream: to share the natural freshness of Canadian spring water with people around the world. Years later, our family decided to turn that dream into reality, with one clear mission: <strong>To bring premium Canadian spring water to the world while preserving its natural quality, purity, and character.<\\/strong><\\/p>\",\"text_color\":\"#cbd5e1\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"91ddd0ae\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":44},\"width_tablet\":{\"unit\":\"%\",\"size\":100},\"width_mobile\":{\"unit\":\"%\",\"size\":100},\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"6e9db140\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/stevencanadaehwater.local\\/wp-content\\/uploads\\/causes_assets\\/canadian_road_journey.webp\"},\"image_size\":\"full\",\"align\":\"center\",\"_border_radius\":{\"unit\":\"px\",\"top\":\"16\",\"right\":\"16\",\"bott